import{_ as l,C as e,o as r,c as o,j as a,a as p,E as s,a3 as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"坐忘论·坐忘枢翼","description":"坐忘论附篇精读：三戒为枢，定慧为翼；五时七候总摄修道进程，并含松紧尺度与安全边界。","frontmatter":{"title":"坐忘论·坐忘枢翼","description":"坐忘论附篇精读：三戒为枢，定慧为翼；五时七候总摄修道进程，并含松紧尺度与安全边界。","category":"guide","aliases":["坐忘枢翼","坐忘论枢翼","坐忘论精读之九"],"source":["坐忘论","司马承祯"],"outline":[2,3]},"headers":[],"relativePath":"daoism/daoist-classics/zuowang-lun/chapter-08.md","filePath":"daoism/daoist-classics/zuowang-lun/chapter-08.md","lastUpdated":1789714390000}'),g={name:"daoism/daoist-classics/zuowang-lun/chapter-08.md"};function c(b,t,u,m,x,v){const i=e("DaoReadingPrelude"),n=e("DaoTextReading"),d=e("DaoKeywordCards");return r(),o("div",null,[t[0]||(t[0]=a("h1",{id:"坐忘论·坐忘枢翼",tabindex:"-1"},[p("坐忘论·坐忘枢翼 "),a("a",{class:"header-anchor",href:"#坐忘论·坐忘枢翼","aria-label":'Permalink to "坐忘论·坐忘枢翼"'},"​")],-1)),s(i,{title:"唯灭动心，不灭照心",summary:"「枢」是枢纽、关键，「翼」是辅翼、展开。本篇把前七篇浓缩为三戒（简缘、无欲、静心），又以「心有五时、身有七候」描述修行由心渐静、定慧相生，直至炼神合道的完整进程。它回答的是七篇之外那些实操问题：收心怎样掌握松紧？如何判断是真定还是强制压心？定中出现异象怎么办？",points:[{label:"立三戒",text:"简缘、无欲、静心——外简其缘，内寡其欲，中心常静。"},{label:"明总诀",text:"唯灭动心，不灭照心；制而无著，放而不逸。"},{label:"定尺度",text:"以无事为真定，以有事为应迹；束心太急，急则成病。"}],hint:"篇末「延数千岁」「炼形为气」等属道教神仙学的宗教性身体观。精读时应区分其原典宗教意义，与今天可以直接实行的调心原则。"}),t[1]||(t[1]=a("h2",{id:"【原典层】原文",tabindex:"-1"},[p("【原典层】原文 "),a("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),t[2]||(t[2]=a("p",null,[a("strong",null,"一、坐忘的基本方法")],-1)),s(n,{paragraphs:["夫欲修道成真，先去邪僻之行，外事都绝，无以干心，然后端坐，内观正觉。","觉一念起，即须除灭，随起随制，务令安静。","其次，虽非的有贪著，浮游乱想，亦尽灭除，昼夜勤行，须臾不替。","唯灭动心，不灭照心，但冥虚心，不冥有心，不依一物，而心常住。"]}),t[3]||(t[3]=a("p",null,[a("strong",null,"二、为何此法难信、难行")],-1)),s(n,{paragraphs:["此法玄妙利益甚深，自非夙有道缘、信心无二者，莫能信重。","虽知诵读其文，仍须辩识真伪，所以者何？声色昏心，邪佞惑耳，人我成性，自是病深，心与道隔，理难晓悟。"]}),t[4]||(t[4]=a("p",null,[a("strong",null,"三、三戒与调心的松紧尺度")],-1)),s(n,{paragraphs:["若有心归至道，深生信慕，先受三戒，依戒修行，在终如始，乃得真道。其三戒者，一曰简缘，二曰无欲，三曰静心。","勤行此三戒，而无懈退者，则无心求道而道自来。经云：人能虚心无为，非欲于道，道自归之。","由此言之，简要之法，实可信哉，实可贵哉。然则凡心躁竞，其来固久，依戒息心，其事甚难。","或息之而不得，暂得而还失，去留交战，百体流汗，久久柔挺，方乃调熟。莫以暂收不得，遂废平生之业。","少得静已，则行立坐卧之时，涉事喧阓之处，皆须作意安之。有事无事，常若无心，处静处喧，其志唯一。","若束心太急，急则成病，气发狂痴，是其候也。"]}),t[5]||(t[5]=a("p",null,[a("strong",null,"四、真定的定义与动静关系")],-1)),s(n,{paragraphs:["心若不动，又须放任，宽急得中，常自调适，制而无著，放而不逸，处喧无恶，涉事无恼者，此真定也。","不以涉事无恼，故求多事，不以处喧无动，故来就喧。","以无事为真定，以有事为应迹。若水镜之为鉴，则遇物而见形。"]}),t[6]||(t[6]=a("p",null,[a("strong",null,"五、定慧关系及定中异象")],-1)),s(n,{paragraphs:["善巧方便，唯能入定，发慧迟速，则不由人。","勿于定中急急求慧，求慧则伤定，伤定则无慧。定不求慧，而慧自生，此真慧也。","慧而不用，实智若愚，益资定慧，双美无极。","若定中念想，则有多感，众邪百魅，随心应现，真人老君，神异诡怪，是其祥也。","唯定心之上，豁然无覆，定心之下，旷然无基，旧业永消，新业不造，无所缠碍，迥脱尘网，行而久之，自然得道。"]}),t[7]||(t[7]=a("p",null,[a("strong",null,"六、心有五时")],-1)),s(n,{paragraphs:["夫得道之人，心有五时，身有七候。","心有五时者，一动多静少；二动静相半；三静多动少；四无事则静，事触还动；五心与道合，触而不动。","心至此地，始得安乐，罪垢灭尽，无复烦恼。"]}),t[8]||(t[8]=a("p",null,[a("strong",null,"七、身有七候")],-1)),s(n,{paragraphs:["身有七候者，一举动顺时，容色和悦；二夙疾普消，身心轻爽；三填补夭伤，还元复命；四延数千岁，名曰仙人；五链形为气，名曰真人；六炼气成神，名曰神人；七炼神合道，名曰至人。","其于鉴力，随候益明，得至道成，慧乃圆备。","虽久学定心，身无五时七候者，促龄秽质，色谢归空，自云慧觉，复称成道，求诸通理，实所未然，可谓谬矣。"]}),t[9]||(t[9]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[p("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(d,{items:[{term:"邪僻之行",pinyin:["xié","pì","zhī","xíng"],meaning:"不正、偏僻、有害的行为（伤害他人、欺骗邪佞、贪残纵欲、以修道之名求利等）。伦理不是定外附加的规则，而是定的基础。"},{term:"无以干心",pinyin:["wú","yǐ","gān","xīn"],meaning:"干，干犯、扰动。使外在事务不再频繁侵入内心。「外事都绝」的最终目的不是绝对封闭的环境，而是使心获得不受干扰的修习条件。"},{term:"内观正觉",pinyin:["nèi","guān","zhèng","jué"],meaning:"内观，返回来观察自己的心念、情绪和执著如何生起；正觉，端正、清明、不受邪想支配的觉察（清醒/如实/正直/不随）。"},{term:"随起随制",pinyin:["suí","qǐ","suí","zhì"],meaning:"念头随时生起便随时调节。「制」不一定是强制，更接近看见、截止、不续、返回当下——重点在「觉」在「除」前。"},{term:"浮游乱想",pinyin:["fú","yóu","luàn","xiǎng"],meaning:"没有明确目的却不断漂浮迁移的念头（无目的回忆、虚构对话、随意设想）。看似无害，却使心不能稳定。"},{term:"须臾不替",pinyin:["xū","yú","bù","tì"],meaning:"顷刻也不间断。非指昼夜不眠或全天紧张监控，而是强调修习具有连续性：坐时、行时、应对事务时皆有觉察。"},{term:"唯灭动心，不灭照心",pinyin:["wéi","miè","dòng","xīn","bù","miè","zhào","xīn"],meaning:"动心是随境妄动攀缘之心，照心是清醒觉察之心。只应止息妄动，不应使觉照一并熄灭——本篇总纲之一，也是辨别真定与昏沉的根本尺度。"},{term:"冥虚心",pinyin:["míng","xū","xīn"],meaning:"「但冥虚心，不冥有心」文字古奥或涉版本问题。大意：使虚妄浮动之心沉寂，不使本有觉照之心陷入昏冥。所寂灭者虚妄攀缘，所保留者本有觉照。"},{term:"不依一物",pinyin:["bù","yī","yī","wù"],meaning:"不把任何境界当作必须攀附的固定支点（声色、呼吸感受、身体某处、空白状态、清静体验、神异景象、「我正在入定」的意识）。与【收心】「住无所有」一致。"},{term:"信心无二",pinyin:["xìn","xīn","wú","èr"],meaning:"对大道和正法的信心专一，不因暂时得失而摇摆。不意味着不能辨伪或提问——下一句恰恰说「仍须辨识真伪」：方向坚定而方法审慎。"},{term:"简缘",pinyin:["jiǎn","yuán"],meaning:"三戒之一。精简使心攀附、耗散的因缘：不以功利机心结交，不主动扩大无必要关系，必要关系做到适度而不黏著。总摄【断缘】【简事】。"},{term:"无欲",pinyin:["wú","yù"],meaning:"三戒之一。不是毁灭全部正常需要，而是不以占有为安、不把喜好当作必需、不追求声色名利与修道异能。总摄【真观】。"},{term:"静心",pinyin:["jìng","xīn"],meaning:"三戒之一。不是意识空白，而是动念能觉、觉而不随、灭动不灭照、不依一物而心常住。总摄【收心】【泰定】。"},{term:"在终如始",pinyin:["zài","zhōng","rú","shǐ"],meaning:"从开始直到最终都以同样的慎重与勤勉坚持三戒。越接近后段，越要防止因定慧所得而重新生欲。"},{term:"躁竞",pinyin:["zào","jìng"],meaning:"躁动、争竞。凡心躁竞并非一日形成，而是长期习惯的结果——所以初静时反而不适，这是正常阶段。"},{term:"柔挺",pinyin:["róu","tǐng"],meaning:"底本文字较难解，可能涉及异文。结合全文，与调柔刚强、使紧张执拗之心渐趋柔顺有关。关键在「久久」，不是一时猛烈。"},{term:"喧阓",pinyin:["xuān","huì"],meaning:"喧闹的市井、人群环境。修习渐熟后，即使处理必要事务、身处喧闹，也要有意保护心的安定。"},{term:"束心太急",pinyin:["shù","xīn","tài","jí"],meaning:"强迫自己完全无念、一念出现便严厉自责、长时间屏息紧绷、为追求定境严重减少睡眠等。本篇最重要的安全警告：急则成病。"},{term:"宽急得中",pinyin:["kuān","jí","dé","zhōng"],meaning:"调心既不能过于宽松，也不能过于急迫。不是永远固定的力度，而要根据当下散、紧、昏、明的状态随时调节。"},{term:"制而无著，放而不逸",pinyin:["zhì","ér","wú","zhuó","fàng","ér","bù","yì"],meaning:"收摄时便收摄而不执著于控制与静境；放松时便放松而不陷入散漫。收摄而不僵硬，放松而不散漫——松紧调节的最高概括。"},{term:"应迹",pinyin:["yìng","jì"],meaning:"事情到来时所作的处理，只是清静心随缘显现的应事痕迹。「以无事为真定，以有事为应迹」：清静是体，应事是用，应事结束即复归无事。"},{term:"善巧方便",pinyin:["shàn","qiǎo","fāng","biàn"],meaning:"人所能安排的入定条件：合适环境、端正坐姿、简缘减欲、调节松紧、念起不随、规律练习。人只能创造虚静清明的条件，不能直接制造本慧。"},{term:"实智若愚",pinyin:["shí","zhì","ruò","yú"],meaning:"具有真实智慧的人外表反像不逞聪明的朴拙者。非故意装傻，而是不抢先表现、不事事发表见解、不以知识建立权威。"},{term:"众邪百魅，随心应现",pinyin:["zhòng","xié","bǎi","mèi","suí","xīn","yìng","xiàn"],meaning:"各种鬼魅邪异之象随内心想念而呈现。关键在「随心」——不应立即认定为外在真实存在；即使显现的是真人、老君等神圣形象，也可能是定中想念所现。"},{term:"豁然无覆，旷然无基",pinyin:["huò","rán","wú","fù","kuàng","rán","wú","jī"],meaning:"定心之上开阔明朗，没有观念、形象与执著覆盖；定心之下广大无依，没有固定对象作为支撑。上无覆、下无基，而觉照仍然明朗——不是坠入虚无，而是无所著的清明。"},{term:"迥脱尘网",pinyin:["jiǒng","tuō","chén","wǎng"],meaning:"远离原有罗网。「尘网」不是社会本身，而是名利网、毁誉网、欲望网、人我网、自是网。"},{term:"五时",pinyin:["wǔ","shí"],meaning:"心的五个阶段：动多静少 → 动静相半 → 静多动少 → 无事则静事触还动 → 心与道合触而不动。「时」不是固定时长，而是修心进展的阶段。"},{term:"七候",pinyin:["qī","hòu"],meaning:"身的七种征候：容色和悦 → 身心轻爽 → 还元复命 → 仙人 → 真人 → 神人 → 至人。「候」是征候、表现，更鲜明地体现道教形神修炼与神仙学。"},{term:"鉴力",pinyin:["jiàn","lì"],meaning:"明镜般的照见能力：觉察念头、洞察因果、辨别真伪、由本知末。「随候益明」——随着身心转化加深，观照能力越来越清明。"},{term:"促龄秽质",pinyin:["cù","líng","huì","zhì"],meaning:"促龄，寿命短促；秽质，形质未道化。本篇以此批评只有自称慧觉而无身心实际转化的情况。现代视角下，寿命身体状况受复杂因素影响，不能据此判定修行真假。"}]}),t[10]||(t[10]=h("",213))])}const q=l(g,[["render",c]]);export{y as __pageData,q as default};
